#!/usr/bin/env python3
"""Write Test/Synth.lean: the synthetic distractor families of EVAL_PLAN §4.1 (10.9, 4.1
decision 2). Test-only axioms, never in the library. Usage: python3 Test/gen_synth.py"""
import os
K = 32
out = ['/-',
       'Synthetic distractor families of EVAL_PLAN §4.1 (milestone 7c). Generated by',
       '`Test/gen_synth.py`; do not edit. Test-only: the library never imports this module.',
       '',
       'Goal (SPEC 7.3): `∀ x y z w : Nat, x ≤ y → y ≤ z → z ≤ w → x ≤ w` with `Nat.le_trans` and',
       'k distractors `monoᵢ`, i < k, all of the form `∀ m n, R m n → R (f m) (f n)`:',
       '- S:  `f` is one shared `Synth.S.s : Nat → Nat`, `R` is `≤` on `Nat`;',
       '- T1: distinct `Synth.T1.fᵢ : Nat → Nat`, `R` is `≤` on `Nat`;',
       '- T2: distinct structures `Synth.T2.Cᵢ`, each with its own `LE` instance, `fᵢ : Cᵢ → Cᵢ`;',
       '- T3: distinct predicates `Synth.T3.Pᵢ : Nat → Nat → Prop`, `f` one shared `Synth.T3.s`.',
       '-/', '', 'namespace Synth', '', 'namespace S', 'axiom s : Nat → Nat']
out += [f'axiom mono{i} : ∀ m n : Nat, m ≤ n → s m ≤ s n' for i in range(K)]
out += ['end S', '', 'namespace T1']
for i in range(K):
    out += [f'axiom f{i} : Nat → Nat', f'axiom mono{i} : ∀ m n : Nat, m ≤ n → f{i} m ≤ f{i} n']
out += ['end T1', '', 'namespace T2']
for i in range(K):
    out += [f'structure C{i} where val : Nat',
            f'instance instLEC{i} : LE C{i} := ⟨fun a b => a.val ≤ b.val⟩',
            f'axiom f{i} : C{i} → C{i}',
            f'axiom mono{i} : ∀ m n : C{i}, m ≤ n → f{i} m ≤ f{i} n']
out += ['end T2', '', 'namespace T3', 'axiom s : Nat → Nat']
for i in range(K):
    out += [f'axiom P{i} : Nat → Nat → Prop', f'axiom mono{i} : ∀ m n : Nat, P{i} m n → P{i} (s m) (s n)']
out += ['end T3', '', 'end Synth', '']
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'Synth.lean'), 'w').write('\n'.join(out))
